const tot=bs=>bs.reduce((a,b)=>{a.ing+=b.ingresos;a.des+=b.descuentos;a.apo+=b.aportes;a.emp+=b.aportesEmp;a.neto+=b.neto;a.costo+=b.costo;return a},{ing:0,des:0,apo:0,emp:0,neto:0,costo:0});
const hist=(p,usuario,accion,nota)=>p.hist.push({ts:new Date().toISOString(),usuario,accion,nota:nota||''});
