/* ================= procesos especiales ================= */
function mesesEn(rel,pp0,n){let k=0;for(let i=0;i<n;i++){const pp=perAdd(pp0,i);if(rel.ingreso<=perIni(pp)&&(!rel.cese||rel.cese>=perFin(pp)))k++}return k}
