 const vauto=t.vacSolicitudes?Math.min(e.reg_vac,Math.max(0,yrs*e.reg_vac-goz)):0;e.dias_vac_pend=o&&o.vac!==''&&o.vac!=null?Number(o.vac)||0:vauto;
 const s1=g1-6,gIni=pick([(y-1)+'-'+pad(g1)+'-01',y+'-'+pad(s1)+'-01',y+'-'+pad(g1)+'-01']);const gPag=(t.nomProcesos||[]).some(x=>x.tipo==='Gratificación'&&x.empresaId===rel.empresaId&&x.estado!=='Calculado'&&x.ref>=gIni.slice(0,7)&&x.ref<=cese.slice(0,7)&&semDe(x.ref)===gIni.slice(0,7)&&x.items.some(i=>i.relId===rel.id));e.meses_grati_trunc=gPag?0:mesesEn({ingreso:rel.ingreso,cese},gIni.slice(0,7),6);
