 if(p.estado==='Aprobado')acts=(can('nomina.aprobar')?B('no_perDevolver','Devolver a revisión','d'):'')+(can('nomina.cerrar')?B('no_perCerrar','Cerrar periodo','p'):pill('Esperando cierre','warn'));
 if(p.estado==='Cerrado')acts=(can('nomina.reabrir')?B('no_perReabrir','Reabrir periodo','d'):'')+(can('nomina.procesar')&&bs.some(b=>!b.pub)?B('no_perPublicar','Publicar boletas','p'):'');
 const incs=p.inc||[],auto=(t.nomPrestamos||[]).filter(l=>l.estado!=='Solicitado'&&l.estado!=='Rechazado'&&trel(t,l.relId)&&trel(t,l.relId).empresaId===p.empresaId).flatMap(l=>l.cron.filter(q=>q.periodo===p.periodo).map(q=>({l,q})));
