function liqDoc(rel,fecha,motivo,res,estado){const t=T(),e=temp(t,rel.empresaId),c=e.moneda,p=tper(t,rel),v=res.env||{};
 return `<div class="no_doc"><header><div><h3>${esc(e.nombre)}</h3><div class="muted">RUC ${esc(e.doc)}</div></div><div style="text-align:right"><h3>Liquidación de beneficios sociales</h3><div class="muted">${esc(estado)}</div></div></header>
 <section><dl><div><dt>Trabajador</dt><dd>${esc(tnm(t,rel))}</dd></div><div><dt>Documento</dt><dd>${esc((p.tipoDoc||'')+' '+(p.doc||''))}</dd></div><div><dt>Ingreso</dt><dd>${fd(rel.ingreso)}</dd></div><div><dt>Cese</dt><dd>${fd(fecha)}</dd></div><div><dt>Motivo</dt><dd>${esc(motivo||'—')}</dd></div><div><dt>Tiempo de servicios</dt><dd>${(m=>Math.floor(m.m/12)+' a '+m.m%12+' m '+m.d+' d')(md(rel.ingreso,fecha))}</dd></div><div><dt>Remuneración computable</dt><dd class="num">${mon((v.basico||0)+(v.asig_fam||0),c)}</dd></div><div><dt>Régimen laboral</dt><dd>${esc(datos(t,rel.id).regimen)}</dd></div></dl></section>
 <section>${res.lineas.length?res.lineas.map(l=>howLine(l,c)).join(''):'<span class="muted">No corresponde ningún concepto con los datos ingresados.</span>'}</section><div class="no_neto"><div class="muted">Total neto de la liquidación</div><b>${mon(res.total,c)}</b></div>
 <section class="muted" style="font-size:12.5px">Documento de trabajo. Los importes salen de los conceptos del proceso «Liquidación» y de los parámetros vigentes a la fecha de cese; valida los parámetros marcados como ejemplo antes de pagar.</section></div>`}
function vBeneficios(){const t=T(),k=ui.no_btab=ui.no_btab||'grati',pro=can('nomina.procesar');let b='';
 if(PT[k]){const tp=PT[k][0],ps=t.nomProcesos.filter(x=>x.tipo===tp&&(!ui.emp||x.empresaId===ui.emp)).sort((a,b)=>b.ref.localeCompare(a.ref)),sel=ps.find(x=>x.id===ui.no_proc)||ps[0];
  b=`<div class="ph"><span class="muted">${k==='grati'?'El monto aprobado entra solo a la planilla del mes de pago como concepto de gratificación.':k==='cts'?'El depósito se calcula por el semestre anterior al mes de depósito, con la última gratificación.':'Reparto de la participación en las utilidades del ejercicio, por días y por remuneraciones.'}</span>${pro?`<button class="btn p" data-a="no_procNew" data-k="${k}">Nuevo proceso</button>`:''}</div>
  ${ps.length?`<div class="tw"><table><thead><tr><th>Proceso</th><th>Empresa</th><th>Estado</th><th class="no_r">Trabajadores</th><th class="no_r">Total</th></tr></thead><tbody>${ps.map(x=>`<tr class="click" data-a="no_procSel" data-id="${x.id}" ${sel===x?'style="background:var(--accent-soft)"':''}><td><b>${prLbl(x)}</b></td><td>${empN(x.empresaId)}</td><td>${pill(x.estado==='Pagado'?(tp==='CTS'?'Depositado':'Pagado'):x.estado,x.estado==='Pagado'?'ok':x.estado==='Aprobado'?'acc':'warn')}</td><td class="no_r">${x.items.length}</td>${R(x.total,temp(t,x.empresaId).moneda)}</tr>`).join('')}</tbody></table></div>`:emptyState('Aún no hay procesos de '+PT[k][1].toLowerCase(),'<span>Crea el proceso, revisa la hoja de cada trabajador y envíalo a aprobación.</span>',pro?`<button class="btn p" data-a="no_procNew" data-k="${k}">Nuevo proceso</button>`:'')}
  ${sel?(()=>{const c=temp(t,sel.empresaId).moneda,B=(a,l,kk)=>`<button class="btn s ${kk||''}" data-a="${a}" data-id="${sel.id}">${l}</button>`;
   return `<div class="ph" style="border-top:1px solid var(--line)"><div><h3>${esc(tp)} · ${prLbl(sel)} · ${empN(sel.empresaId)}</h3><span class="muted">Creado por ${esc(sel.por)}${sel.aprobadoPor?' · aprobado por '+esc(sel.aprobadoPor):''}${sel.renta?' · renta neta '+mon(sel.renta,c):''}</span>${k==='util'&&(n=>n<=pnum(t,'util_min_trab',TODAY)?`<div style="margin-top:6px"><span class="no_ej">La empresa tiene ${n} trabajadores activos: la participación obliga a empresas con más de ${fnum(pnum(t,'util_min_trab',TODAY))}. Verifica si corresponde repartir.</span></div>`:'')(t.relaciones.filter(r=>r.empresaId===sel.empresaId&&r.estado==='Activo').length)||''}</div><div class="row">${sel.estado==='Calculado'&&pro?B('no_procDel','Anular','d')+B('no_procCalc','Recalcular'):''}${sel.estado==='Calculado'&&can('nomina.aprobar')?B('no_procApr','Aprobar','p'):''}${sel.estado==='Aprobado'&&pro?B('no_procPag','Marcar como '+PT[k][4],'p'):''}</div></div>
   ${sel.items.length?`<div class="tw"><table><thead><tr><th>Trabajador</th>${k==='util'?'<th class="no_r">Por días</th><th class="no_r">Por remuneraciones</th>':k==='grati'?'<th class="no_r">Gratificación</th><th class="no_r">Bonif. extraordinaria</th>':'<th class="no_r">Meses</th>'}<th class="no_r">Total</th><th></th></tr></thead><tbody>${sel.items.map(i=>`<tr><td>${whoCell(trel(t,i.relId))}</td>${k==='util'?R(lineOf(i,'u_dias'),c)+R(lineOf(i,'u_rem'),c):k==='grati'?R(lineOf(i,'g_grati'),c)+R(lineOf(i,'g_bonif'),c):`<td class="no_r">${fnum(((i.lineas[0]||{}).vars||{}).meses_cts||0)}</td>`}<td class="no_r"><b>${mon(i.total,c)}</b></td><td style="text-align:right"><button class="btn s" data-a="no_procHoja" data-id="${sel.id}" data-rel="${i.relId}">Hoja de liquidación</button></td></tr>`).join('')}<tr class="no_tf"><td>Total</td><td${k==='cts'?'':' colspan="2"'}></td>${R(sel.total,c)}<td></td></tr></tbody></table></div>`:'<div class="pb muted">Ningún trabajador de la empresa tiene derecho a este beneficio según su régimen.</div>'}`})():''}`}
 if(k==='prov'){const ps=t.nomPeriodos.filter(p=>(!ui.emp||p.empresaId===ui.emp)&&bolsDe(t,p).length).sort((a,b)=>b.periodo.localeCompare(a.periodo)),sel=ps.find(p=>p.id===ui.no_provPer)||ps[0],pv3=bs=>['prov_cts','prov_grati','prov_vac'].map(a=>P2(bs.reduce((s,o)=>s+lineOf(o,a),0)));
  b=ps.length?`<div class="ph"><span class="muted">La provisión mensual reparte en el año el costo de CTS, gratificaciones y vacaciones. Sale de los conceptos de provisión del catálogo.</span><select class="in" id="no_provPer" data-c="no_provPer" style="width:auto" aria-label="Periodo">${ps.map(p=>`<option value="${p.id}"${sel===p?' selected':''}>${esc(perLbl(p))}</option>`).join('')}</select></div>
  <div class="tw"><table><thead><tr><th>Periodo</th><th>Empresa</th><th class="no_r">CTS</th><th class="no_r">Gratificación</th><th class="no_r">Vacaciones</th><th class="no_r">Total provisionado</th></tr></thead><tbody>${ps.map(p=>{const v=pv3(bolsDe(t,p)),c=temp(t,p.empresaId).moneda;return `<tr><td><b>${perName(p.periodo)}</b></td><td>${empN(p.empresaId)}</td>${R(v[0],c)}${R(v[1],c)}${R(v[2],c)}<td class="no_r"><b>${mon(v[0]+v[1]+v[2],c)}</b></td></tr>`}).join('')}</tbody></table></div>
  <div class="ph" style="border-top:1px solid var(--line)"><h3>Detalle por trabajador · ${esc(perLbl(sel))}</h3></div><div class="tw"><table><thead><tr><th>Trabajador</th><th class="no_r">CTS</th><th class="no_r">Gratificación</th><th class="no_r">Vacaciones</th><th class="no_r">Total</th></tr></thead><tbody>${bolsDe(t,sel).map(o=>{const v=pv3([o]),c=temp(t,sel.empresaId).moneda;return `<tr><td>${whoCell(trel(t,o.relId))}</td>${R(v[0],c)}${R(v[1],c)}${R(v[2],c)}${R(v[0]+v[1]+v[2],c)}</tr>`}).join('')}</tbody></table></div>`:emptyState('Aún no hay provisiones','<span>Se generan al calcular la planilla de cada periodo.</span>')}
 if(k==='liq'){const rs=t.relaciones.filter(r=>esPE(t,r.empresaId)&&(!ui.emp||r.empresaId===ui.emp)).sort((a,b)=>(a.estado===b.estado?0:a.estado==='Cesado'?-1:1)||nm(a).localeCompare(nm(b),'es')),rel=rs.find(r=>r.id===ui.no_liqRel)||rs[0];
  if(!rel)b=emptyState('No hay colaboradores de empresas peruanas','<span>La liquidación usa el paquete de país Perú.</span>');else{const ces=rel.estado==='Cesado',fecha=ces?rel.cese:(ui.no_liqFecha&&ui.no_liqFecha>=rel.ingreso?ui.no_liqFecha:TODAY),mot=ces?rel.motivoCese:(ui.no_liqMot||'Renuncia'),res=calcLiq(t,rel,fecha,{vac:ui.no_liqVac,indem:ui.no_liqInd}),sv=t.nomLiquidaciones.filter(l=>!ui.emp||trel(t,l.relId).empresaId===ui.emp);
   b=`<div class="pb" style="display:flex;flex-direction:column;gap:14px"><div class="form" style="padding:0"><label>Colaborador<select class="in" id="no_liqRel" data-c="no_liqRel">${rs.map(r=>`<option value="${r.id}"${r===rel?' selected':''}>${esc(nm(r))}${r.estado==='Cesado'?' · cesado el '+fd(r.cese):''}</option>`).join('')}</select></label>
   <label>Fecha de cese${ces?'':' (hipotética)'}<input class="in" type="date" id="no_liqFecha" data-c="no_liqFecha" value="${fecha}"${ces?' disabled':''}></label>
   <label>Motivo<select class="in" id="no_liqMot" data-c="no_liqMot"${ces?' disabled':''}>${['Renuncia','Fin de contrato','Despido','Mutuo acuerdo','Jubilación'].map(m=>`<option${m===mot?' selected':''}>${m}</option>`).join('')}${ces&&!['Renuncia','Fin de contrato','Despido','Mutuo acuerdo','Jubilación'].includes(mot)?`<option selected>${esc(mot)}</option>`:''}</select></label>
   <label>Días de vacaciones no gozadas<input class="in" type="number" min="0" id="no_liqVac" data-c="no_liqVac" value="${esc(ui.no_liqVac??'')}" placeholder="${res.vacMod?'Según vacaciones aprobadas: '+res.vacAuto:'Ingresa el saldo pendiente'}"></label>
   <label class="full row" style="flex-direction:row;font-weight:500"><input type="checkbox" class="chk" id="no_liqInd" data-chk="no_liqInd"${ui.no_liqInd?' checked':''}>Incluir indemnización por despido arbitrario (lo decide la empresa; el sistema solo la calcula)</label></div>
   ${ces?'':'<div class="note">Esta persona sigue activa: es una <b>simulación</b> para estimar el costo de una salida. La liquidación definitiva se emite cuando el cese esté registrado en su ficha.</div>'}
   ${liqDoc(rel,fecha,mot,res,ces?'Cese registrado':'Simulación')}
   <div class="row" style="justify-content:flex-end">${pro?`<button class="btn p" data-a="no_liqSave" data-id="${rel.id}">${ces?'Emitir liquidación':'Guardar simulación'}</button>`:''}</div></div>
   ${sv.length?`<div class="ph" style="border-top:1px solid var(--line)"><h3>Liquidaciones guardadas</h3></div><div class="tw"><table><thead><tr><th>Trabajador</th><th>Cese</th><th>Tipo</th><th class="no_r">Total</th><th>Registrada por</th><th></th></tr></thead><tbody>${sv.map(l=>`<tr><td>${whoCell(trel(t,l.relId))}</td><td class="num">${fd(l.fecha)}</td><td>${pill(l.estado,l.estado==='Emitida'?'ok':'')}</td>${R(l.total,cur(trel(t,l.relId)))}<td class="muted">${esc(l.por)} · ${fd(l.creado)}</td><td style="text-align:right"><button class="btn s" data-a="no_liqVer" data-id="${l.id}">Ver hoja</button></td></tr>`).join('')}</tbody></table></div>`:''}`}}
 return CSS+pageHead('Nómina','Beneficios sociales','','Gratificaciones, CTS y utilidades se calculan como procesos aparte de la planilla mensual, con su propia hoja de liquidación.')+
 `<div class="panel">${tabsH('no_btab',[['grati','Gratificaciones'],['cts','CTS'],['util','Utilidades'],['prov','Provisiones'],['liq','Liquidación de beneficios']])}${b}</div>`}

/* ================= Préstamos y adelantos ================= */
function firstOpen(t,emp){let pp=CURP;for(let i=0;i<24;i++){const p=t.nomPeriodos.find(x=>x.empresaId===emp&&x.periodo===pp);if(!p||p.estado==='Abierto')return pp;pp=perAdd(pp,1)}return pp}
function topeAdel(t,rel){const pct=pnum(t,'adelanto_tope_pct',TODAY),dia=Math.min(30,+TODAY.slice(8,10)),dev=P2(sueldoA(t,rel,TODAY)/30*dia),ya=t.nomPrestamos.filter(l=>l.relId===rel.id&&l.tipo==='Adelanto'&&(l.estado==='Solicitado'||(l.estado==='Aprobado'&&saldo(l)>0))).reduce((s,l)=>s+l.monto,0);return{pct,dia,dev,tope:Math.max(0,P2(dev*pct/100-ya)),ya}}
function vPrestamos(){const t=T(),all=t.nomPrestamos.filter(l=>{const r=trel(t,l.relId);return r&&(!ui.emp||r.empresaId===ui.emp)}),ls=all.filter(l=>!ui.no_lf||l.estado===ui.no_lf).sort((a,b)=>(a.estado==='Solicitado'?0:1)-(b.estado==='Solicitado'?0:1)||b.solicitado.localeCompare(a.solicitado));
 return CSS+pageHead('Nómina','Préstamos y adelantos',can('nomina.procesar')?'<button class="btn p" data-a="no_loanNew">Registrar préstamo o adelanto</button>':'','Las cuotas aprobadas se descuentan solas en la planilla del periodo que corresponde.')+
 `<div class="kpis"><div class="kpi"><b class="num" style="font-size:22px">${mon(all.filter(l=>l.estado==='Aprobado').reduce((s,l)=>s+saldo(l),0))}</b><span>Saldo por cobrar</span></div><div class="kpi"><b class="num">${all.filter(l=>l.estado==='Solicitado').length}</b><span>Solicitudes por aprobar</span></div><div class="kpi"><b class="num" style="font-size:22px">${mon(all.filter(l=>l.estado==='Aprobado').reduce((s,l)=>s+l.cron.filter(c=>c.periodo===CURP&&c.estado==='Pendiente').reduce((a,c)=>a+c.monto,0),0))}</b><span>Por descontar en ${perName(CURP)}</span></div><div class="kpi"><b class="num">${fnum(pnum(t,'adelanto_tope_pct',TODAY))} %</b><span>Tope del adelanto sobre lo devengado</span></div></div>
 <div class="panel"><div class="ph"><select class="in" id="no_lf" data-c="no_lf" style="width:auto" aria-label="Estado">${[['','Todos los estados'],['Solicitado','Por aprobar'],['Aprobado','En curso'],['Pagado','Pagados'],['Rechazado','Rechazados']].map(o=>`<option value="${o[0]}"${(ui.no_lf||'')===o[0]?' selected':''}>${o[1]}</option>`).join('')}</select><span class="muted num">${ls.length} registro(s)</span></div>
 ${ls.length?loanTable(ls,true,true):emptyState(all.length?'Nada con ese estado':'Aún no hay préstamos ni adelantos','<span>Los colaboradores pueden pedirlos desde «Mis boletas», o el equipo de nómina puede registrarlos aquí.</span>',can('nomina.procesar')?'<button class="btn p" data-a="no_loanNew">Registrar préstamo o adelanto</button>':'')}</div>`}

/* ================= Declaraciones y archivos ================= */
