/* ================= eventos de dominio ================= */
const treg=(rel,tipo,detalle,fecha)=>{const t=T();if(!t.nomTreg||!esPE(t,rel.empresaId))return;t.nomTreg.push({id:nid('ntr'),relId:rel.id,tipo,fecha:fecha||TODAY,detalle,estado:'Pendiente',declarado:'',constancia:''})};
